DROP TABLE IF EXISTS `users`;
CREATE TABLE `users`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(25) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `real_name` varchar(25) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'KREWS DEV',
  `password` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `two_factor_secret` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `two_factor_recovery_codes` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `two_factor_confirmed` tinyint(1) NOT NULL DEFAULT 0,
  `two_factor_confirmed_at` timestamp NULL DEFAULT NULL,
  `mail` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `mail_verified` enum('0','1') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `account_created` int NOT NULL,
  `account_day_of_birth` int NOT NULL DEFAULT 0,
  `last_login` int NOT NULL DEFAULT 0,
  `last_online` int NOT NULL DEFAULT 0,
  `motto` varchar(127) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `look` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'hr-115-42.hd-195-19.ch-3030-82.lg-275-1408.fa-1201.ca-1804-64',
  `gender` enum('M','F') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'M',
  `rank` int NOT NULL DEFAULT 1,
  `hidden_staff` tinyint(1) NOT NULL DEFAULT 0,
  `credits` int NOT NULL DEFAULT 2500,
  `pixels` int NOT NULL DEFAULT 500,
  `points` int NOT NULL DEFAULT 10,
  `online` enum('0','1','2') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `auth_ticket` varchar(256) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `ip_register` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `ip_current` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT 'Have your CMS update this IP. If you do not do this IP banning won\'t work!',
  `machine_id` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `home_room` int NOT NULL DEFAULT 0,
  `referral_code` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `website_balance` int UNSIGNED NOT NULL DEFAULT 0,
  `secret_key` varchar(40) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `pincode` varchar(11) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `extra_rank` int NULL DEFAULT NULL,
  `team_id` bigint UNSIGNED NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `username`(`username` ASC) USING BTREE,
  UNIQUE INDEX `id`(`id` ASC) USING BTREE,
  UNIQUE INDEX `id_2`(`id` ASC) USING BTREE,
  UNIQUE INDEX `id_3`(`id` ASC) USING BTREE,
  UNIQUE INDEX `users_referral_code_unique`(`referral_code` ASC) USING BTREE,
  INDEX `account_created`(`account_created` ASC) USING BTREE,
  INDEX `last_login`(`last_login` ASC) USING BTREE,
  INDEX `last_online`(`last_online` ASC) USING BTREE,
  INDEX `figure`(`motto` ASC, `look` ASC, `gender` ASC) USING BTREE,
  INDEX `auth_ticket`(`auth_ticket` ASC) USING BTREE,
  INDEX `users_team_id_foreign`(`team_id` ASC) USING BTREE,
  CONSTRAINT `users_team_id_foreign` FOREIGN KEY (`team_id`) REFERENCES `website_teams` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

