  `can_trade` enum('0','1') CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT '1',
  `is_citizen` enum('0','1') CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT '0',
  `citizen_level` int NOT NULL DEFAULT 0,
  `helper_level` int NOT NULL DEFAULT 0,
  `tradelock_amount` int NOT NULL DEFAULT 0,
