  `cfh_abusive` int NOT NULL DEFAULT 0 COMMENT 'Amount of abusive CFHs have been send.',
  `cfh_warnings` int NOT NULL DEFAULT 0 COMMENT 'Amount of warnings a user has received.',
  `cfh_bans` int NOT NULL DEFAULT 0 COMMENT 'Amount of bans a user has received.',
  `block_following` enum('0','1') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `block_friendrequests` enum('0','1') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `block_roominvites` enum('0','1') CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT '0',
  `volume_system` int NOT NULL DEFAULT 100,
  `volume_furni` int NOT NULL DEFAULT 100,
  `volume_trax` int NOT NULL DEFAULT 100,
  `old_chat` enum('0','1') CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT '0',
  `block_camera_follow` enum('0','1') CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT '0',
  `chat_color` int NOT NULL DEFAULT 0,
  `home_room` int NOT NULL DEFAULT 0,
  `online_time` int NOT NULL DEFAULT 0 COMMENT 'Total online time in seconds.',
  `tags` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT 'Arcturus Emulator;',
  `club_expire_timestamp` int NOT NULL DEFAULT 0,
  `login_streak` int NOT NULL DEFAULT 0,
  `rent_space_id` int NOT NULL DEFAULT 0,
  `rent_space_endtime` int NOT NULL DEFAULT 0,
  `hof_points` int NOT NULL DEFAULT 0,
  `block_alerts` enum('0','1') CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT '0',
  `talent_track_citizenship_level` int NOT NULL DEFAULT -1,
  `talent_track_helpers_level` int NOT NULL DEFAULT -1,
  `ignore_bots` enum('0','1') CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT '0',
  `ignore_pets` enum('0','1') CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT '0',
  `nux` enum('0','1') CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT '0',
  `mute_end_timestamp` int NOT NULL DEFAULT 0,
  `allow_name_change` enum('0','1') CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT '0',
  `perk_trade` enum('0','1') CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT '0' COMMENT 'Defines if a player has obtained the perk TRADE. When hotel.trading.requires.perk is set to 1, this perk is required in order to trade. Perk is obtained from the talen track.',
  `forums_post_count` int NULL DEFAULT 0,
  `ui_flags` int NOT NULL DEFAULT 1,
  `has_gotten_default_saved_searches` tinyint(1) NOT NULL DEFAULT 0,
