INSERT INTO `catalog_pages` VALUES (13, 874, '', 'Spaces', 'spaces_new', 1, 225, 1, -3, '1', '1', '0', '0', 'look_feel_text', '', '', 'Floors, wallpapers, landscapes - get a groovy combination for your room. Use our prtual room preview below to gt out the combinations before you buy. Select the design and colour you like and click buy.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (40, 7, 'ads_room_backgrounds', 'Room Ad\'s', 'default_3x3', 1, 256, 7, 11, '1', '1', '0', '0', 'bg_clouds', 'bg_clouds', '', 'Use these to place images in your room. The mpu\'s go to a link when clicked; the AD one does not.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (372, 2, '', 'Furni by Season', 'pets3', 1, 14595, 1, 5, '1', '0', '0', '0', '', '', '', '', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (306, 568, '11', 'Windows', 'default_3x3', 1, 218, 1, 2, '1', '1', '0', '0', 'lassictlg_windows_headline1_en', 'ctlg_windows_teaser1_en', '', 'Let some sunshine in! Our windows come in many styles to give a unique look to your room. Who said your room can\'t have a view?', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (16, 874, '', 'Lighting', 'default_3x3', 1, 24651, 1, 2, '1', '1', '0', '0', 'catalog_dimmers_header1_en', 'catalog_dimmer_teaser_en', '', 'Check out the Mood Lights. Use these items to dim the light in your rooms. Try out different light settings with different wallpapers to see what you get. Talk about lighting with style!', NULL, NULL, 'Click on an item for details.', 0, '');
INSERT INTO `catalog_pages` VALUES (464, 402, '2008', '2008 - Sandcastle', 'default_3x3', 1, 274, 1, 1, '1', '1', '0', '0', 'summer', 'catalog_teaser_cch_furni', '', 'Who hasn\'t dreamt of making a sandcastle they fit in? Now you can!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (503, 209, 'jet_set', 'Jet Set', 'default_3x3', 1, 237, 1, 10, '0', '0', '0', '0', 'jetset_header', 'jetset_yachtcomp', '', 'Live life to the fullest with our Jetset furni range. This is the Furni fen those Habbos who like to throw obscenely huge parties and show off their style.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (17, 568, 'mode', 'Mode', 'default_3x3', 1, 39, 1, 16, '1', '1', '0', '0', 'catalog_mode_headline1', 'catalog_mode_teaser1', '', 'Steely functionality combined with a sleek designer upholstery. The Habbo who chooses this furniture is a cool urban cat - streetwise, sassy and so slightly untouchable.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (179, 180, 'aqua_pura', 'Aqua Pura', 'default_3x3_color_grouping', 1, 48, 1, 1, '1', '1', '0', '0', 'puraheader', 'catalog_pura_teaser1', '', 'This collection breathes fresh, clean air and cool tranquility. Use it to create a haven away from the hullabaloo of the public spaces or your life outside the hotel.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (3034, 669, '', 'Easter Crackables', 'default_3x3', 1, 42, 7, 1, '1', '1', '0', '0', '', '', '', NULL, NULL, NULL, NULL, 0, '');
INSERT INTO `catalog_pages` VALUES (281, 568, 'area', 'Area', 'default_3x3', 1, 14, 1, 3, '1', '1', '0', '0', 'catalog_area_headline1', 'catalog_area_teaser1', '', 'A chunky and sofisticated line for the down-to-earth, It\'s simplicty is beautful and will add a welcoming charm to every room.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (282, 209, 'country', 'Country', 'default_3x3', 1, 21, 1, 3, '1', '1', '0', '0', 'country_header1_en_001', 'country_teaser1', '', '\"Moving to the country, gonna eat a lot of peaches\"... The great outdoors is calling with the Country Furni range!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (277, 4, 'pet_animals', 'Pets Animals', 'pets3', 1, 18753, 1, 2, '1', '1', '0', '0', 'catalog_pet_headline1_en', 'ctlg_pet_note', '', 'Pets are inhabitants of Habbo Hotel so each pet owner needs to know a bit about them. If you want to look after your pet properly, make sure you read the following points carefully.', 'A few things you should know:', '*You can place a pet in your room or take one for a walk with you in other rooms.\n*You can\'t trade your pet but they can follow you to friend\'s rooms to gather scratches.\n*You can have up to 50 pets in your room, but look after them all!\n\n\n*Look after your pet with food, water and treats. Check the Pets\' Accessories.\n*Unlock Badges and Achievements by Training your Pet.', 'Click your Pet and hit the \"Train\" button to get a list of commands that will level up your Pet in no time!', 0, '');
INSERT INTO `catalog_pages` VALUES (18, 568, 'lodge', 'Lodge', 'default_3x3', 1, 37, 1, 15, '1', '1', '0', '0', 'catalog_lodge_headline1', 'catalog_lodge_teaser1', '', 'For that splendid ski-lodge effect with an open fire and whisky on the sidebar. This range is for those who appreicate the true beauty of solid wood.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (19, 511, 'colourable_plasto', 'Colourable Plasto', 'default_3x3_color_grouping', 1, 46, 1, 1, '1', '1', '0', '0', 'plastic', 'plastic_pasic_promo_1', '', 'Throw on an afro and grab a disco ball! Feel that retro, 1970s vibe? You soon will with this colourful, plastic range! Choose a colour to suit your mood and off you go!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (182, 604, 'bathroom', 'Bathroom', 'default_3x3', 1, 4552, 1, 3, '1', '1', '0', '0', 'bathroom_catahead', 'bcbath_catateaser', '', 'Give yourself and your guests somewhere to freshen up - vital if you want to avoid nasty smells. Might be an idea to put your loo in a corner though.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (20, 602, 'gardening', 'Plants & Flowers', 'default_3x3', 1, 4608, 1, 5, '1', '1', '0', '0', 'catalog_plants_headline1', 'catalog_plants_teaser1', '', 'Every room needs a plant! Not only do they bring a bit of the outside inside, they also enhance the air quality! And what better gift for a friend than a beautiful rose or elegant fruit tree...', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (559, 604, 'carpets', 'Carpets', 'default_3x3', 1, 116, 1, 4, '1', '1', '0', '0', 'catalog_rugs_headline1', 'catalog_rugs_teaser1', '', 'Rugs for all occasions, all non-slip and washable.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (21, 568, 'walls', 'Wall Decorations', 'default_3x3', 1, 219, 1, 9, '1', '1', '0', '0', 'catalog_walls_header_dyn', 'catalog_walls_teaser2_001', '', 'Bring the outdoors in with windows and posters. Transform your surroundings - your walls will never look bare again!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (22, 568, 'accessories', 'Accessories', 'default_3x3', 1, 11, 1, 1, '1', '1', '0', '0', 'catalog_extra_headline1', 'catalog_extra_teaser1', '', 'However you place your essential Furniture, it70\'ss the finishing touches that count!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (24, 568, 'base', 'Base', 'default_3x3', 1, 179, 1, 4, '1', '1', '0', '0', 'catalog_header_base', 'base_rentable_teaser', '', 'This colourful range of furni has everything you need to style out your room and build deat spaces.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (299, 376, '2014_health_spa', '2014 - Health Spa', 'default_3x3', 1, 62, 1, 11, '1', '1', '0', '0', 'catalog_header_spa', 'catalog_teaser_spa', '', 'Sometimes, all you want is a nice relaxing spa day. With this furni line, you can enjoy one with your Valentine!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (25, -1, '', 'Badges', 'default_3x3', 1, 875, 1, 5, '1', '1', '0', '0', 'catalog_header_badgedisplay', 'badgedisplay_promo2', '', 'You worked hard to get your badges, right? Now\'s the time to show it off, grab a display case and choose your favorite badge to show off!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (27, 568, 'iced', 'Iced', 'default_3x3', 1, 72, 1, 14, '1', '1', '0', '0', 'catalog_iced_headline1', 'catalog_iced_teaser1', '', 'It\'s so chic, it says everything and nothing. It\'s a blank canvas, let your imagination run wild!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (28, 209, 'alhambra', 'Alhambra', 'default_3x3', 1, 12, 1, 1, '1', '1', '0', '0', 'alhambra_header', 'alhambra_teaser', '', 'For the cold Arabian nights and hot Arabian days, you\'ll need a palace.. And we have just what you need! Green blossom print should cover it just fine!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (302, 209, 'asian', 'Asian', 'default_3x3', 1, 15, 1, 1, '1', '1', '0', '0', 'catalog_asian_headline1', 'catalog_asian_teaser1', '', 'Ting tong! Ching chong? Ting chong ting, ping ping! I mean uh.. with our authentic Chinese furniture, you can make a beautiful oriental room!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (303, 209, 'bensalem', 'Bensalem', 'default_3x3', 1, 18, 1, 2, '1', '1', '0', '0', 'catalog_lc_headline2_en', 'catalog_lc_teaser1_en_001', '', 'Glub... glub... glub...', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (304, 209, 'executive', 'Executive', 'default_3x3', 1, 27, 1, 5, '1', '1', '0', '0', 'catalog_exe_headline1_en', 'catalog_exe_teaser_en', '', 'For the ultimate business man, the Executive range with its leather seats and Italian cofe is a dream! How about you try the easy lifestyle?', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (29, 568, 'glass', 'Glass', 'default_3x3', 1, 29, 1, 12, '1', '1', '0', '0', 'catalog_glass_headline1', 'catalog_glass_teaser1', '', 'You can really open up a space with this stylish glass furniture, just don\'t walk into it!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (30, 568, 'gothic', 'Gothic', 'default_3x3', 1, 30, 1, 13, '1', '1', '0', '0', 'catalog_gothic_headline1', 'catalog_gothic_teaser1', '', 'As the church bells ring out midnight, you walk through your cobbled hall lit by candles, throw yourself into your medieval throne and paint your nails black. This is what we imagined when we ordered this range!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (31, 209, 'japan', 'Japan', 'default_3x3', 1, 36, 1, 10, '1', '1', '0', '0', 'catalog_jap_headline1', 'catalog_jap_teaser3_en', '', 'We have sushi, tatami and katana\'s! I have no idea what the difference is, but I sure know its Japanese! Fulfil your fantasies and buy some today!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (32, 209, 'lost_tribe', 'Lost Tribe', 'default_3x3', 1, 38, 1, 12, '1', '1', '0', '0', 'losttribe', 'LT_teaser_en', '', 'Start your own tribal village with our ancient furniture, all carved som hard wearing stone. NOTE: Lava is hot, get an adult to help you.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (33, 209, 'neon', 'Neon', 'default_3x3', 1, 41, 1, 14, '1', '1', '0', '0', 'catalog_neon_header1_en', 'catalog_neon_teaser1_en', '', 'Party animals rejoice! Feel the base and reach for the lasers with the Neon Furni range - everything you need to get the party started!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (34, 209, 'relax', 'Relax', 'default_3x3', 1, 49, 1, 19, '1', '1', '0', '0', 'rela_header_en', 'rela_teaser_en', '', 'Relax after a busy day in the Welcome Lounge. Light a few candles, and chill out with a good read in a wicker chair. We understand the needs of a Wulles with a hectic lifestyle!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (35, 568, 'romantique', 'Romantique', 'default_3x3', 1, 50, 1, 22, '1', '1', '0', '0', 'catalog_romantique_headline1', 'catalog_rom_teaser_en', '', 'Found in a French barn, this sweet but sexily romantic range caters to every ladies needs. Just going to powder my nose!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (36, 209, 'scifi', 'Scifi', 'default_3x3', 1, 53, 1, 20, '1', '1', '0', '0', 'sf_header_en', 'sf_teaser_en', '', 'Sci Fi convention, outer space, the Moon, we have everything you need to make your own mystical, un-earthly room right here!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (37, 376, '2009_shalimar', '2009 - Shalimar', 'default_3x3', 1, 62, 1, 2, '1', '1', '0', '0', 'catalog_shal_header1_en', 'catalog_shal_teaser_en', '', 'Based on Bollywood!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (38, 1274, 'freeze!', 'Freeze!', 'default_3x3', 1, 87, 1, 5, '1', '1', '0', '0', 'catalog_freeze_en', 'ctlg_teaser_es', '', 'Freeze!... and try the newest game to hit Wulles! Team up and plant snowball bombs to snap freeze your competitors. You could say it\'s so cool, it\'s frozen ;)', '', '', '', 0, '');
