INSERT INTO `catalog_pages` VALUES (42, 568, '6', 'Rollers', 'default_3x3', 1, 222, 1, 6, '1', '1', '0', '0', 'catalog_roller_headline1', 'catalog_teaser_rollers_en', '', 'Move your imagination. This cool stuff is more than suitable for business and pleasure... Habbo rollers for games and queues. Now available in multipacks.', '', '', '', 0, '');
