INSERT INTO `catalog_pages` VALUES (44, 209, 'twilight', 'Twilight', 'default_3x3', 1, 52, 1, 21, '1', '1', '0', '0', 'catalog_twilight_header_en', 'ctlg_pic_ads_twi_mist', '', 'I\'ve never read the book, all I know is it has vampires playing basket ball and some heart throb called Edward Cullen, but the furni looks good!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (45, 1274, 'battle_banzai', 'Banzai', 'default_3x3', 1, 78, 1, 1, '1', '1', '0', '0', 'catalog_battleBanzai_header_en', 'catalog_battleBanzai_teaser', '', 'Bigger, Better, Bouncier - it\'s Battle Banzai! Now YOU set the rules for your own game, in your own room. You got the Banzai Power!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (272, 602, 'urban', 'Streets', 'default_3x3', 1, 504, 1, -1, '1', '1', '0', '0', 'urban_header_en', 'urban_teaser_en', '', 'New York City styled furni range, Urban is perfect for any street, alleyway or road. Rubbish bins, street lights and benches, all the Urban furniture you need!', '', '', '', 0, '');
