INSERT INTO `catalog_pages` VALUES (50, 376, '2010_bling', '2010 - Bling', 'default_3x3', 1, 62, 1, 3, '1', '1', '0', '0', 'catalog_header_bling_en', 'catalog_teaser_bling11', '', 'Did someone speak in glamour? Chic? Lux? So you\'re speaking the language of Bonnie Blonde, my friend!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (51, 209, 'organo', 'Organo', 'default_3x3', 1, 235, 1, 16, '1', '1', '0', '0', 'organo_cata_header', 'organo_teaser', '', 'The latest range from Ann Summers, the Orgie line. Made of soft, wipe clean plastic, its perfect for any three, four or fivesome!', '', '', '', 0, '');
