INSERT INTO `catalog_pages` VALUES (99964, 99218, 'effects', 'Effects', 'default_3x3', 1, 82, 7, 4, '1', '1', '0', '0', 'catalog_wired_header3_en', 'ctlg_pic_wired_effects', '', 'Effects are what happens after you activate a Trigger. To program an Effect, place it in a room, double click on it and set it up! You will always need to stack a Trigger with the Effect to make it work.', NULL, '', 'Click on an item to see what the Effect does!', 0, '');
INSERT INTO `catalog_pages` VALUES (99965, 99218, 'conditions', 'Conditions', 'default_3x3', 1, 83, 7, 5, '1', '1', '0', '0', 'catalog_wired_header4_en', 'ctlg_pic_wired_conditions', '', 'Conditions are specific things that need to be done before a Trigger will work. If you want to use a Condition, you will need to stack it with a Trigger and Effect.', NULL, '', 'Click on an item to see what the Condition does!', 0, '');
