INSERT INTO `catalog_pages` VALUES (366, 387, 'library', 'Library', 'default_3x3', 1, 264, 1, 16, '1', '1', '0', '0', 'catalog_header_classics', 'Library', '', 'The room description was \"There\'s nothing like a good book...\"', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (104, 209, 'drago', 'Drago', 'default_3x3', 1, 110, 1, 4, '1', '1', '0', '0', 'drago_catalog_header2', 'drago_catalog_teaser2', '', 'Dungeon furniture, the perfect range to create your torturous cellars!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (105, 568, 'dark_pura', 'Dark Pura', 'default_3x3', 1, 48, 1, 9, '1', '0', '0', '0', 'puraheader', 'catalog_pura_teaser1', '', 'The cleanest, freshest range. You can almost hear it breathe cool and tranquility within your room.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (374, 372, 'easter', 'Easter', 'default_3x3', 1, 181, 1, 2, '1', '0', '0', '0', 'catalog_easter_headline1', 'catalog_easter_teaser1', '', '', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (106, 209, 'boutique', 'Boutique', 'default_3x3', 1, 74, 1, 2, '1', '1', '0', '0', 'boutique_catalog_01', 'boutique_catalog_teaser_01', '', 'The boutique range is just the thing if you want to own a high end fashion store in Milan, but are on a budget.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (365, 387, 'club_mammoth', 'Club Mammoth', 'default_3x3', 1, 264, 1, 3, '1', '1', '0', '0', 'catalog_header_classics', 'jan18_classic11_internal', '', 'Club Mammoth was first opened to only HC and VIP (when it was introduced) members. The room description was \"Monumental and magnificant.\"', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (364, 387, 'star_lounge', 'Star Lounge', 'default_3x3', 1, 264, 1, 21, '1', '1', '0', '0', 'catalog_header_classics', 'spromo_Star_Lounge', '', 'While also popular, this room was also used for many Celebrity Visits.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (363, 387, 'oriental', 'Oriental', 'default_3x3', 1, 264, 1, 18, '1', '1', '0', '0', 'catalog_header_classics', 'spromo_Classic_Tea_Room', '', 'The room description was \"A soothing atmosphere and amazing tea brews.\"', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (362, 387, 'ice_cafe', 'Ice Cafe', 'default_3x3', 1, 264, 1, 14, '1', '1', '0', '0', 'catalog_header_classics', 'classic5_furnis', '', 'The Ice Cafe was used a a meeting place in Habbo Experience for Chaplin and his friends.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (107, 2, 'zabbo_groups', 'Habbo Groups', 'guilds', 1, 203, 1, 11, '1', '1', '0', '0', 'catalog_groups_en', 'catalog_groupsteaser_en', '', 'Habbo Groups are a great way to stay in touch with your friends and share your interests with others. Each Group has a homeroom that can be decorated by other Group members, members can also purchase exclusive Group Furni that can be customised with your Group colours!', '', '* Get together with people you get together with!\r\n* Co-op room decorating for group members\r\n* Show off your group badge!\r\n* Get some neat Furni in your group\'s colours!', 'What\'s So Great About Habbo Groups?', 0, '');
INSERT INTO `catalog_pages` VALUES (108, 107, 'group_furni', 'Group Furni', 'guild_furni', 1, 203, 1, 1, '1', '1', '0', '0', 'catalog_groups_en', '', 'guild_custom_furni', 'Show off your Group spirit with the new customisable Furni. Select your Group and then get your furni in your Groups colours.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (377, 372, 'new_years', 'New Years', 'default_3x3', 1, 91, 1, 5, '1', '0', '0', '0', '', '', '', '', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (109, 209, 'youtube', 'Youtube', 'default_3x3', 1, 188, 1, 25, '1', '1', '0', '0', 'catalog_header_tv', 'yttv', '', 'Remember when Habbo had YouTube TVs? Well it can again, with KrewsTube! Check it out at krews.org', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (110, 209, 'vikings', 'Vikings', 'default_3x3', 1, 208, 1, 23, '1', '1', '0', '0', 'vikings_catalog_header', 'catalog_teaser_vikings', '', 'From weapon racks and heads on spikes, to ornate hand-carved wooden chairs and benches. This furni has everything you need and more to create the Viking village of your dreams. With furni available in clan colours, you can display your true loyalty with pride!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (111, 209, '0', 'Palooza', 'default_3x3', 1, 227, 1, 3, '1', '1', '0', '0', 'catalog_teaser_palooza', 'catalog_teaser_palooza', '', 'Create your own stage and outdoor festival area. We\'ve got stages, fencing and even vending machines!', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (112, 209, 'wild_wild_west', 'Wild Wild West', 'default_3x3', 1, 229, 1, 24, '1', '1', '0', '0', 'catalog_header_wwest', 'catalog_teaser_wildwest', '', 'From the Shoot\'em Up Saloon to the Sheriff\'s Office, and all the floor tiles, cacti and tumbleweeds in between...Wild West furni has made it\'s way to town.', '', '', '', 0, '');
