INSERT INTO `catalog_pages` VALUES (78, 277, 'terriers', 'Terriers', 'pets', 1, 66, 1, 14, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'The Cairn Terrier is one of the oldest terrier breeds. From the Scottish Highlands, it was used for hunting prey among the cairns! Different breeds have different colours!', 'Name your Terrier:', 'Pick a colour:', 'Pick a breed:\n', 0, '');
INSERT INTO `catalog_pages` VALUES (77, 277, 'crocs', 'Crocs', 'pets', 1, 22, 1, 3, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'Scaly skin, growls and snaps! Security for your room or used to scare your friends - this surprisingly loving Croc can be yours.', 'Name your Croc:', 'Pick a colour:', 'Pick a breed:', 0, '');
INSERT INTO `catalog_pages` VALUES (76, 277, 'cats', 'Cats', 'pets', 1, 20, 1, 2, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'Fluff, whiskers, meows and purrs! These cute little critters make great playmates and will keep you entertained.', 'Name your Cat:', 'Pick a colour:', 'Pick a breed:', 0, '');
INSERT INTO `catalog_pages` VALUES (75, 277, 'dogs', 'Dogs', 'pets', 1, 24, 1, 4, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'Wet noses, paws and woofs! You\'re about to enter the world of Habbo Dogs. An adorable and cuddly ball of fur awaits you with a waggling tail.', 'Name your Dog:', 'Pick a colour:', 'Pick a breed:', 0, '');
INSERT INTO `catalog_pages` VALUES (2512, 25, 'badge_display', 'Badge Display', 'badge_display', 1, 35800, 1, 1, '1', '1', '0', '0', 'catalog_header_badgedisplay', 'badges', '', 'Express yourself with Badges!<br>Put those useless Duckets to use and show off your personality with our wide range of badges.', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (123721, 12371, 'diamonds', 'Diamonds Hidden', 'default_3x3', 1, 92, 7, 2, '1', '1', '0', '0', '', 'catalog_diamond21_teaser', '', 'You can exchange your Zabbo diamonds here for Exchange furniture, which you can use in a trade or simply exchange for actual diamonds. Please note, the redeem window will say you\'re redeeming for credits, ignore this - you will be given diamonds.', ' ', ' ', NULL, 0, '');
