INSERT INTO `catalog_pages` VALUES (4, -1, 'pets', 'Pets', 'default_3x3', 1, 8, 1, 4, '1', '1', '0', '0', 'catalog_frontpage_headline_shop_EN', '', '', '', '', '', '', 0, '');
INSERT INTO `catalog_pages` VALUES (821, 4, 'baby_pet_animals', 'Baby Pet Animals', 'pets3', 1, 228, 1, 4, '1', '1', '0', '0', 'babypets_cata_header', 'ctlg_babypet_note', '', 'They\'re friendly. They\'re cute. They\'re here to win your hearts. Who are they? Baby pets! ALL NEW Kittens, puppies, piglets are storming their way through the hotel and joining the Bear Cubs and Terriers. Available via breeding boxes or sale.', 'A few things you should know:', '*You can place a pet in your room or take one for a walk with you in other rooms.\n*You can\'t trade your pet but they can follow you to friend\'s rooms to gather scratches.\n*You can have up to 50 pets in your room, but look after them all!\n\n\n*Look after your pet with food, water and treats.\nCheck the Pets\' Accessories.\n*Unlock Badges and Achievements by Training your Pet.', 'Click your Pet and hit the \"Train\" button to get a list of commands that will level up your Pet in no time!', 0, '');
INSERT INTO `catalog_pages` VALUES (1199, 821, 'kittens', 'Kittens', 'pets', 1, 228, 1, 1, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'Leaping their way around the Hotel, these fluffy furballs are here to steal your heart...and your yarn!', '', 'Name your pet:', '', 0, '');
INSERT INTO `catalog_pages` VALUES (11100, 821, 'puppies', 'Puppies', 'pets', 1, 228, 1, 2, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'So soft and cuddly, these playful pups are certain to melt your heart. From Labradors to Dalmatians, there\'s a breed for everyone!', '', 'Name your pet:', '', 0, '');
INSERT INTO `catalog_pages` VALUES (11101, 821, 'piglets', 'Piglets', 'pets', 1, 228, 1, 3, '1', '1', '0', '0', 'catalog_pet_headline1', '', '', 'OINK! Partial to a good roll in the mud, these playful piggies have trotted into the hotel and are ready for fun!', '', 'Name your pet:', '', 0, '');
