INSERT INTO `website_shop_articles` VALUES (1, 1, 'Bronze Package', 'Embark on your Habbo adventure with the Bronze Package – your essential starter kit for the virtual world. Start building your dream rooms, customize your avatar, and get access to basic perks that will make your stay more enjoyable.', 'https://i.imgur.com/1VGFYSL.gif', '#c5630f', 500, 2, 5000, 5000, 100, 'VipParties2', NULL, 0, 1, '2025-03-13 14:16:45', '2025-03-13 14:16:45');
INSERT INTO `website_shop_articles` VALUES (2, 1, 'Silver Package', 'The Silver Package is designed for Habbos who are ready to take their experience up a notch. Enjoy a substantial boost of in-game currency and exclusive access to items that will set you apart from the crowd.', 'https://i.imgur.com/5NBdR0z.gif', '#dddddd', 1000, 3, 10000, 10000, 300, 'VipParties2_Top100', NULL, 0, 1, '2025-03-13 14:16:46', '2025-03-13 14:16:46');
INSERT INTO `website_shop_articles` VALUES (3, 1, 'Gold VIP', 'The Gold VIP package is the epitome of Habbo luxury, reserved for those who crave the ultimate in virtual prestige. Enjoy unparalleled access to exclusive items, premium features, and a status symbol that will make heads turn wherever you go in the Hotel.', 'https://i.imgur.com/NiVvRrs.gif', '#E4A317FF', 1500, 4, 15000, 15000, 500, 'VipParties2_Top10', NULL, 0, 1, '2025-03-13 14:16:46', '2025-03-13 14:16:46');
